-- Fotos de Grok, lote 2, tanda 1 (IDs 14-23). Registro de lo insertado por REST el 16-oct-2026; NO es una migración.
-- Aceptadas: 16, 17, 18, 19, 20, 23. Rechazadas: 14, 15, 21, 22 (ver kimiko/informes/fotos-grok.md).
-- Borradores: publicada = false, ficha_verificada = false. Idempotente.

insert into public.plants (id, slug, nombre_es, nombre_latino, categoria, grok_id, image_cientifica_url, ficha_cientifica, ficha_mistica, ficha_verificada, publicada)
select (select coalesce(max(id), 0) + 1 from public.plants), 'ganoderma', 'Ganoderma (Reishi)', 'Ganoderma lucidum', 'Maestras', 16, '/images/plants/ganoderma-grok.jpg',
  '{"familia_botanica":"Ganodermataceae (hongo)","parte_usada":"Cuerpo fructífero (el «sombrero» y el pie), seco","principios_activos":["Triterpenos (ácidos ganodéricos)","Polisacáridos (beta-glucanos)","Esteroles"],"propiedades":["Uso tradicional como tónico general en la medicina asiática","Apoyo tradicional en épocas de cansancio"],"indicaciones":["Uso tradicional en Asia oriental como tónico general","Uso tradicional para acompañar épocas de cansancio o estrés"],"posologia":"Tradicionalmente se toma el hongo seco en decocción larga o en extracto. No indicamos dosis: consulta a un profesional sanitario, sobre todo si tomas medicación. Si los síntomas duran más de una semana, acude a tu médico.","contraindicaciones":["Embarazo y lactancia (no hay datos de seguridad)","Si tomas anticoagulantes, antiagregantes o medicación para la tensión, consulta antes con tu médico","Si vas a someterte a una operación, avisa al equipo médico: puede influir en la coagulación","Personas con alergia a los hongos o con trastornos de la coagulación","No dar a niños"],"fuentes":[{"titulo":"Memorial Sloan Kettering — Reishi mushroom (ficha de hierbas y suplementos)","url":"https://www.mskcc.org/cancer-care/integrative-medicine/herbs/reishi-mushroom"}]}'::jsonb,
  '{"chakra":"Corona","elemento":"Éter","planeta_regente":"Luna","energia":"Quieta y longeva","simbolismo":"En China se le llama «hongo de la inmortalidad» y aparece en el arte como símbolo de larga vida.","uso_ceremonial":"En la tradición taoísta se asocia a la calma y a la práctica de meditación.","afinidad_ayurvedica":"Sin correspondencia clásica ayurvédica: es de la tradición china"}'::jsonb, false, false
where not exists (select 1 from public.plants where nombre_latino = 'Ganoderma lucidum' or slug = 'ganoderma' or grok_id = 16);

insert into public.plants (id, slug, nombre_es, nombre_latino, categoria, grok_id, image_cientifica_url, ficha_cientifica, ficha_mistica, ficha_verificada, publicada)
select (select coalesce(max(id), 0) + 1 from public.plants), 'ginkgo', 'Ginkgo', 'Ginkgo biloba', 'Maestras', 17, '/images/plants/ginkgo-grok.jpg',
  '{"familia_botanica":"Ginkgoaceae","parte_usada":"Hoja","principios_activos":["Flavonoides (quercetina, kaempferol)","Ginkgólidos","Bilobálido"],"propiedades":["Uso tradicional para la circulación periférica","Uso tradicional para la memoria en la edad avanzada"],"indicaciones":["Uso tradicional para aliviar la sensación de piernas pesadas y manos frías","Uso tradicional para apoyar la memoria y la concentración en personas mayores"],"posologia":"Se usa la hoja en extractos estandarizados o, más rara vez, en infusión. No indicamos dosis: consulta a un profesional sanitario, sobre todo si tomas medicación. Si los síntomas duran más de una semana, acude a tu médico.","contraindicaciones":["Embarazo y lactancia","Si tomas anticoagulantes o antiagregantes (acenocumarol, warfarina, aspirina), no lo uses sin consultar: aumenta el riesgo de hemorragia","Suspender antes de una operación, según indique el equipo médico","Personas con epilepsia o con tendencia a sangrar","No dar a niños","No usar las semillas ni la pulpa del fruto: pueden ser tóxicas"],"fuentes":[{"titulo":"Agencia Europea del Medicamento — Ginkgo folium (monografía)","url":"https://www.ema.europa.eu/en/medicines/herbal/ginkgo-folium"}]}'::jsonb,
  '{"chakra":"Corona","elemento":"Tierra","planeta_regente":"Sol","energia":"Resistente y serena","simbolismo":"Es un árbol casi sin cambios desde hace cientos de millones de años: símbolo de longevidad y de resistencia.","uso_ceremonial":"En los templos de Asia oriental se planta junto a los santuarios como árbol guardián.","afinidad_ayurvedica":"Sin correspondencia clásica ayurvédica: es de la tradición china"}'::jsonb, false, false
where not exists (select 1 from public.plants where nombre_latino = 'Ginkgo biloba' or slug = 'ginkgo' or grok_id = 17);

insert into public.plants (id, slug, nombre_es, nombre_latino, categoria, grok_id, image_cientifica_url, ficha_cientifica, ficha_mistica, ficha_verificada, publicada)
select (select coalesce(max(id), 0) + 1 from public.plants), 'gordolobo', 'Gordolobo', 'Verbascum thapsus', 'Maestras', 19, '/images/plants/gordolobo-grok.jpg',
  '{"familia_botanica":"Scrophulariaceae","parte_usada":"Flores (y hojas)","principios_activos":["Mucílagos","Saponinas","Flavonoides","Iridoides"],"propiedades":["Emoliente de las mucosas (uso tradicional)","Expectorante suave (uso tradicional)"],"indicaciones":["Uso tradicional para aliviar la tos con mucosidad","Uso tradicional para suavizar la garganta irritada"],"posologia":"Tradicionalmente se usan las flores secas en infusión, colada para retirar los pelillos. No indicamos dosis: consulta a un profesional sanitario, sobre todo si tomas medicación. Si los síntomas duran más de una semana, acude a tu médico.","contraindicaciones":["Embarazo y lactancia (no hay datos suficientes)","No dar a niños pequeños sin consejo del pediatra","Alergia a plantas de la familia de las escrofulariáceas","Colar siempre la infusión: los pelillos de la planta pueden irritar la garganta","Si la tos dura más de una semana o hay fiebre, acude a tu médico"],"fuentes":[{"titulo":"Agencia Europea del Medicamento — Verbasci flos (monografía)","url":"https://www.ema.europa.eu/en/medicines/herbal/verbasci-flos"}]}'::jsonb,
  '{"chakra":"Garganta","elemento":"Aire","planeta_regente":"Saturno","energia":"Suave y protectora","simbolismo":"Su tallo alto y erguido se llamó «vela del pastor»: símbolo de luz que acompaña en el camino.","uso_ceremonial":"En el folclore europeo se colgaba en casa como amuleto de protección.","afinidad_ayurvedica":"Sin correspondencia clásica ayurvédica: es de la tradición europea"}'::jsonb, false, false
where not exists (select 1 from public.plants where nombre_latino = 'Verbascum thapsus' or slug = 'gordolobo' or grok_id = 19);

insert into public.plants (id, slug, nombre_es, nombre_latino, categoria, grok_id, image_cientifica_url, ficha_cientifica, ficha_mistica, ficha_verificada, publicada)
select (select coalesce(max(id), 0) + 1 from public.plants), 'hamamelis', 'Hamamelis', 'Hamamelis virginiana', 'Maestras', 20, '/images/plants/hamamelis-grok.jpg',
  '{"familia_botanica":"Hamamelidaceae","parte_usada":"Hoja y corteza","principios_activos":["Taninos (hamamelitaninos)","Flavonoides","Aceite esencial"],"propiedades":["Astringente (uso tradicional)","Tónica de la piel y de los vasos (uso tradicional)"],"indicaciones":["Uso tradicional externo para aliviar la irritación y el picor leves de la piel","Uso tradicional externo para la sensación de pesadez de piernas"],"posologia":"SOLO USO EXTERNO. Tradicionalmente se aplica en compresas, lociones o pomadas. No indicamos dosis: consulta a un profesional sanitario, sobre todo si tomas medicación. Si los síntomas duran más de una semana, acude a tu médico.","contraindicaciones":["Solo uso externo: no tomar por vía oral","No aplicar sobre heridas abiertas ni piel muy dañada","Alergia a la planta o a sus preparados: probar primero en una zona pequeña","Embarazo y lactancia: consultar antes","No usar en niños pequeños sin consejo del pediatra","Si la irritación empeora o no mejora en pocos días, acude a tu médico"],"fuentes":[{"titulo":"Agencia Europea del Medicamento — Hamamelidis folium (monografía)","url":"https://www.ema.europa.eu/en/medicines/herbal/hamamelidis-folium"},{"titulo":"Agencia Europea del Medicamento — Hamamelidis cortex (monografía)","url":"https://www.ema.europa.eu/en/medicines/herbal/hamamelidis-cortex"}]}'::jsonb,
  '{"chakra":"Plexo solar","elemento":"Agua","planeta_regente":"Luna","energia":"Tranquila y recogida","simbolismo":"Florece en otoño, cuando otras plantas se apagan: símbolo de belleza que llega a destiempo.","uso_ceremonial":"Los pueblos nativos de Norteamérica usaban su vara flexible en rituales de búsqueda de agua.","afinidad_ayurvedica":"Sin correspondencia clásica ayurvédica: es de la tradición norteamericana"}'::jsonb, false, false
where not exists (select 1 from public.plants where nombre_latino = 'Hamamelis virginiana' or slug = 'hamamelis' or grok_id = 20);
